import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';

const Header: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const isActive = (path: string) => location.pathname === path;

  return (
    <header className="header">
      <div className="header-container">
        <Link to="/" className="header-logo">
          <span className="logo-text">Цензура ПД</span>
          <span className="logo-underline"></span>
        </Link>
        
        <nav className="header-nav">
          <div className="nav-main-section">
            <Link 
              to="/" 
              className={`nav-link main-nav-link ${isActive('/') ? 'active' : ''}`}
            >
              <span className="nav-icon">🏠</span>
              <span className="nav-text">Главная</span>
              <span className="nav-underline"></span>
            </Link>
            
            {user && (
              <Link 
                to="/redaction" 
                className={`nav-link main-nav-link ${isActive('/redaction') ? 'active' : ''}`}
              >
                <span className="nav-icon">🖼️</span>
                <span className="nav-text">Редактор</span>
                <span className="nav-underline"></span>
              </Link>
            )}
          </div>
          
          <div className="nav-secondary-section">
            {user ? (
              <>
                <div className="user-actions">
                  <div className="user-info-badge">
                    <span className="user-icon">
                      {user.is_admin ? '👑' : '👤'}
                    </span>
                    <span className="username">{user.username}</span>
                    {user.is_admin && (
                      <span className="admin-badge">Admin</span>
                    )}
                  </div>
                  
                  <div className="action-buttons">
                    <button 
                      onClick={() => navigate('/profile')} 
                      className="action-button profile-button"
                      title="Перейти в профиль"
                    >
                      <span className="button-icon">👤</span>
                      <span className="button-text">Профиль</span>
                      <span className="button-underline"></span>
                    </button>
                    <button 
                      onClick={handleLogout} 
                      className="action-button logout-button"
                      title="Выйти из системы"
                    >
                      <span className="button-icon">🚪</span>
                      <span className="button-text">Выйти</span>
                      <span className="button-underline"></span>
                    </button>
                  </div>
                </div>
              </>
            ) : (
              <>
                <Link 
                  to="/login" 
                  className={`nav-link ${isActive('/login') ? 'active' : ''}`}
                >
                  <span className="nav-icon">🔐</span>
                  <span className="nav-text">Войти</span>
                  <span className="nav-underline"></span>
                </Link>
                <Link 
                  to="/register" 
                  className={`nav-link ${isActive('/register') ? 'active' : ''}`}
                >
                  <span className="nav-icon">📝</span>
                  <span className="nav-text">Регистрация</span>
                  <span className="nav-underline"></span>
                </Link>
              </>
            )}
            
            <Link 
              to="/about" 
              className={`nav-link ${isActive('/about') ? 'active' : ''}`}
            >
              <span className="nav-icon">ℹ️</span>
              <span className="nav-text">О проекте</span>
              <span className="nav-underline"></span>
            </Link>
          </div>
        </nav>
      </div>
    </header>
  );
};

export default Header;
